import { MakeLogicType, afterMount, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import api from 'lib/api'
import { teamLogic } from 'scenes/teamLogic'

import type { Experiment } from '~/types'

export interface ExperimentTabLogicProps {
    featureFlagId: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentTabLogicValues {
    currentProjectId: number | string // teamLogic
    relatedExperiments: Experiment[]
    relatedExperimentsLoadFailed: boolean
    relatedExperimentsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentTabLogicActions {
    loadRelatedExperiments: () => any
    loadRelatedExperimentsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadRelatedExperimentsSuccess: (
        relatedExperiments: Experiment[],
        payload?: any
    ) => {
        relatedExperiments: Experiment[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentTabLogicMeta {
    key: number
}

export type experimentTabLogicType = MakeLogicType<
    experimentTabLogicValues,
    experimentTabLogicActions,
    ExperimentTabLogicProps,
    experimentTabLogicMeta
>

export const experimentTabLogic = kea<experimentTabLogicType>([
    path(['scenes', 'experiments', 'experimentTabLogic']),
    props({} as ExperimentTabLogicProps),
    key((props) => props.featureFlagId),
    connect(() => ({ values: [teamLogic, ['currentProjectId']] })),
    loaders(({ props, values }) => ({
        relatedExperiments: [
            [] as Experiment[],
            {
                loadRelatedExperiments: async () => {
                    // nosemgrep: prefer-codegen-api -- Legacy raw API call with a hand-written URL and an unchecked response type. Use experimentsList() from 'products/experiments/frontend/generated/api' instead.
                    const response = await api.get(
                        `api/projects/${values.currentProjectId}/experiments/?feature_flag_id=${props.featureFlagId}`
                    )
                    return response.results || []
                },
            },
        ],
    })),
    reducers({
        // A retry does not clear this, so the retry banner stays mounted and shows its spinner.
        relatedExperimentsLoadFailed: [
            false,
            {
                loadRelatedExperimentsFailure: () => true,
                loadRelatedExperimentsSuccess: () => false,
            },
        ],
    }),
    listeners(({ cache }) => ({
        loadRelatedExperimentsFailure: ({ errorObject }) => {
            // Count each failure once per mount, because a retry that fails again is the same dead end.
            if (!cache.hasCapturedLoadFailure) {
                cache.hasCapturedLoadFailure = true
                posthog.capture('feature flag experiments tab load failed', { status: errorObject?.status ?? null })
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadRelatedExperiments()
    }),
])
